function clearGenerated(directory: string): void {
	mkdirSync(directory, { recursive: true });
	for (const entry of readdirSync(directory)) {
		if (!entry.endsWith(".test.ts")) continue;
		const path = join(directory, entry);
		if (readFileSync(path, "utf8").startsWith(generatedHeader)) writeFileSync(path, "");
	}
}

clearGenerated(routeDirectory);
clearGenerated(roundTripDirectory);
const adapters = adapterContractFixtures.map((fixture) => fixture.adapter as CodemodAdapterId);
for (const source of adapters)
	for (const target of adapters)
		if (source !== target) {
			writeFileSync(join(routeDirectory, fileName(source, target)), routeSource(source, target));
			writeFileSync(
				join(roundTripDirectory, roundTripFileName(source, target)),
				roundTripSource(source, target),
			);
		}

for (const directory of [routeDirectory, roundTripDirectory])
	for (const entry of readdirSync(directory))
		if (entry.endsWith(".test.ts") && readFileSync(join(directory, entry), "utf8") === "")
			throw new Error(`stale generated route spec: ${join(directory, entry)}`);

console.log(
	`generated ${adapters.length * (adapters.length - 1)} directional and round-trip specs`,
);
